The supplied files need to be updated to define a `Character` class that:

- Rolls six abilities using four six-sided dice and keeps the highest three.
- Exposes accessors for all six abilities.
- Calculates hitpoints as `10 + constitution modifier`.
- Uses mathematically correct floor rounding for negative constitution modifiers.
- Uses only the C++ standard library for randomness.

dnd_character.h
```
#pragma once

#include <random>

namespace dnd_character {

class Character {
public:
    Character();

    int strength() const;
    int dexterity() const;
    int constitution() const;
    int intelligence() const;
    int wisdom() const;
    int charisma() const;
    int hitpoints() const;

private:
    int roll_ability();

    std::mt19937 generator_;
    int strength_;
    int dexterity_;
    int constitution_;
    int intelligence_;
    int wisdom_;
    int charisma_;
};

}  // namespace dnd_character
```

dnd_character.cpp
```
#include "dnd_character.h"

#include <algorithm>
#include <array>
#include <numeric>
#include <random>

namespace dnd_character {

Character::Character()
    : generator_(std::random_device{}()),
      strength_(roll_ability()),
      dexterity_(roll_ability()),
      constitution_(roll_ability()),
      intelligence_(roll_ability()),
      wisdom_(roll_ability()),
      charisma_(roll_ability()) {}

int Character::roll_ability() {
    std::uniform_int_distribution<int> die_roll(1, 6);
    std::array<int, 4> dice{};

    for (int& die : dice) {
        die = die_roll(generator_);
    }

    const int total = std::accumulate(dice.begin(), dice.end(), 0);
    const int lowest = *std::min_element(dice.begin(), dice.end());

    return total - lowest;
}

int Character::strength() const {
    return strength_;
}

int Character::dexterity() const {
    return dexterity_;
}

int Character::constitution() const {
    return constitution_;
}

int Character::intelligence() const {
    return intelligence_;
}

int Character::wisdom() const {
    return wisdom_;
}

int Character::charisma() const {
    return charisma_;
}

int Character::hitpoints() const {
    const int difference = constitution_ - 10;
    const int constitution_modifier =
        difference >= 0 ? difference / 2 : -((-difference + 1) / 2);

    return 10 + constitution_modifier;
}

}  // namespace dnd_character
